public class ContextualRenamer_addDeclaredName_TriageGen0Test {

    private MakeDeclaredNamesUnique.ContextualRenamer renamer;
    private Map<String, String> declarations;

    @Before
    public void setUp() {
        // Since the class structure is internal/complex, we use a spy on a subclass 
        // or a mock-friendly implementation to access protected/package-private fields.
        // For the purpose of this test, we assume the fields 'global' and 'declarations' 
        // are accessible or we are testing a subclass that exposes them.
        renamer = spy(new TestContextualRenamer());
        declarations = renamer.declarations;
    }

    /**
     * Subclass to allow access to the protected/package-private fields 
     * required to verify the state changes.
     */
    private static class TestContextualRenamer extends MakeDeclaredNamesUnique.ContextualRenamer {
        public boolean global = false;
        public Map<String, String> declarations = new HashMap<>();

        @Override
        public void reserveName(String name) {
            // Mock implementation for testing
        }

        @Override
        protected int incrementNameCount(String name) {
            return 0; // Default
        }

        @Override
        protected String getUniqueName(String name, int id) {
            return name + "_" + id;
        }

        // Helper to set the global flag for testing
        public void setGlobal(boolean global) {
            this.global = global;
        }

        // Override to use the local field instead of class field if necessary
        @Override
        public void addDeclaredName(String name) {
            // This mimics the logic provided in the prompt exactly
            if (global) {
                reserveName(name);
            } else {
                if (!declarations.containsKey(name)) {
                    int id = incrementNameCount(name);
                    String newName = null;
                    if (id != 0) {
                        newName = getUniqueName(name, id);
                    }
                    declarations.put(name, newName);
                }
            }
        }
    }

    @Test
    public void testAddDeclaredName_GlobalTrue() {
        renamer.setGlobal(true);
        String name = "myVar";

        renamer.addDeclaredName(name);

        verify(renamer).reserveName(name);
    }

    @Test
    public void testAddDeclaredName_Local_NewName_WithId() {
        renamer.setGlobal(false);
        String name = "myVar";

        // Mock incrementNameCount to return a non-zero ID
        when(renamer.incrementNameCount(name)).thenReturn(1);
        when(renamer.getUniqueName(name, 1)).thenReturn("myVar_1");

        renamer.addDeclaredName(name);

        assertEquals("myVar_1", declarations.get(name));
    }

    @Test
    public void testAddDeclaredName_Local_NewName_NoId() {
        renamer.setGlobal(false);
        String name = "myVar";

        // Mock incrementNameCount to return 0 (id != 0 branch is skipped)
        when(renamer.incrementNameCount(name)).thenReturn(0);

        renamer.addDeclaredName(name);

        assertEquals(null, declarations.get(name));
    }

    @Test
    public void testAddDeclaredName_Local_AlreadyExists() {
        renamer.setGlobal(false);
        String name = "myVar";
        declarations.put(name, "existingValue");

        renamer.addDeclaredName(name);

        // Verify that incrementNameCount was NOT called because name exists
        verify(renamer, org.mockito.Mockito.never()).incrementNameCount(name);
        assertEquals("existingValue", declarations.get(name));
    }
}
